import subprocess, os, shutil
from collections import Counter

def run_pty(base, cols=200):
    cmd=f"stty cols {cols} rows 50; /workspace/executable {base}"
    r=subprocess.run(["script","-q","-c",cmd,"/dev/null"], capture_output=True, text=True)
    return r.stdout

def nested(s, cols=200):
    base="/tmp/tnest"
    shutil.rmtree(base, ignore_errors=True); os.makedirs(base+"/dir")
    for name,sz in [("dir/f0",10000),("dir/f1",s)]:
        with open(os.path.join(base,name),"wb") as f: f.write(b"x"*sz)
    out=run_pty(base, cols)
    res={}
    for line in out.splitlines():
        for key in ["f0","f1","dir"]:
            # name extraction rough
            if key in line.split('│')[0] or (key=="dir" and "dir" in line):
                bar=line.split('│')[-2]
                res[key]=Counter(bar)
    return res

for s in range(0,10001,250):
    res=nested(s)
    print(s, "f0█",res.get("f0",{}).get('█',0), "f1█",res.get("f1",{}).get('█',0), "f1total", sum(v for k,v in res.get("f1",{}).items() if k!=' '), "dir",res.get("dir",{}).get('█',0))
PY"}

