import os, pty, subprocess, fcntl, termios, struct, sys, time, select

def set_winsize(fd, cols, rows=50):
    fcntl.ioctl(fd, termios.TIOCSWINSZ, struct.pack("HHHH", rows, cols, 0, 0))

def run_case(name, stdout_mode, stderr_mode, stdin_mode, cols=120):
    # modes: 'pty' or 'pipe' or 'null'
    masters={}
    slaves={}
    pipes={}
    def setup(mode, label):
        if mode=='pty':
            m,s=pty.openpty(); set_winsize(s, cols); masters[label]=m; slaves[label]=s; return s
        elif mode=='pipe':
            r,w=os.pipe(); pipes[label]=r; return w
        elif mode=='null':
            return subprocess.DEVNULL
    out=setup(stdout_mode,'out')
    err=setup(stderr_mode,'err')
    inn=setup(stdin_mode,'in') if stdin_mode!='pipe' else subprocess.DEVNULL
    # stdin pty needs slave as stdin; fine
    p=subprocess.Popen(["/workspace/executable","-A","/tmp/t3"], stdout=out, stderr=err, stdin=inn, close_fds=True)
    # close slave/write ends in parent
    for label,fd in list(slaves.items()): 
        try: os.close(fd)
        except: pass
    if stdout_mode=='pipe':
        try: os.close(out)
        except: pass
    if stderr_mode=='pipe':
        try: os.close(err)
        except: pass
    # read
    def read_all(fd):
        data=b""
        while True:
            try:
                chunk=os.read(fd,65536)
            except OSError:
                break
            if not chunk: break
            data+=chunk
        return data
    outdata=b""; errdata=b""
    if 'out' in masters: outdata=read_all(masters['out'])
    elif 'out' in pipes: outdata=read_all(pipes['out'])
    if 'err' in masters: errdata=read_all(masters['err'])
    elif 'err' in pipes: errdata=read_all(pipes['err'])
    p.wait()
    lines=outdata.decode('utf-8','replace').splitlines()
    print(name, "exit",p.returncode, "out_lines_len",[len(x) for x in lines[:3]], "first",lines[:2], "err",errdata[:100])

