{"command":"cd /workspace && mkdir -p src && python3 - << 'PY'
import unicodedata, sys
zero=[]
wide=[]
for cp in range(0x110000):
    if 0xD800 <= cp <= 0xDFFF: continue
    ch=chr(cp)
    cat=unicodedata.category(ch)
    eaw=unicodedata.east_asian_width(ch)
    is_zero=False
    if cat in ('Mn','Me'):
        is_zero=True
    elif cat=='Cf' and cp!=0x00AD:
        is_zero=True
    elif cat=='Cc':
        is_zero=True
    elif 0x1160 <= cp <= 0x11FF:
        is_zero=True
    elif cp in (0xFF9E,0xFF9F):
        is_zero=True
    # variation selectors are Mn already
    if is_zero:
        zero.append(cp)
    elif eaw in ('W','F'):
        wide.append(cp)
print("zero count",len(zero),"wide",len(wide),file=sys.stderr)
def ranges(vals):
    out=[]
    start=prev=vals[0]
    for v in vals[1:]:
        if v==prev+1: prev=v
        else: out.append((start,prev)); start=prev=v
    out.append((start,prev)); return out
zr=ranges(zero); wr=ranges(wide)
print("ranges",len(zr),len(wr),file=sys.stderr)
with open('src/width.rs','w') as f:
    f.write("// Unicode display width tables (generated from Unicode character data).\n")
    f.write("// Width 0: combining enclosing/nonspacing marks, format/control chars,\n// and Hangul Jamo medial vowels and trailing consonants.\n")
    f.write("// Width 2: East Asian Wide and Fullwidth characters.\n\n")
    for name,rs in [('ZERO',zr),('WIDE',wr)]:
        f.write(f"const {name}: &[(u32, u32)] = &[\n")
        for a,b in rs:
            f.write(f"    ({a:#x}, {b:#x}),\n")
        f.write("];\n\n")
    f.write(r'''fn in_ranges(ranges: &[(u32, u32)], cp: u32) -> bool {
    ranges.binary_search_by(|&(lo, hi)| {
        if cp < lo {
            std::cmp::Ordering::Greater
        } else if cp > hi {
            std::cmp::Ordering::Less
        } else {
            std::cmp::Ordering::Equal
        }
    }).is_ok()
}

pub fn char_width(c: char) -> usize {
    let cp = c as u32;
    if cp < 0x20 || (0x7f <= cp && cp < 0xa0) {
        0
    } else if in_ranges(ZERO, cp) {
        0
    } else if in_ranges(WIDE, cp) {
        2
    } else {
        1
    }
}

pub fn str_width(s: &str) -> usize {
    s.chars().map(char_width).sum()
}
''')
