// A small command-line option parser reproducing the parsing rules and
// diagnostics of the classic Rust "getopts" interface for this program's
// fixed option set.

#[derive(Clone, Copy, PartialEq, Eq, Debug)]
pub enum HasArg {
    No,
    Maybe,
    Yes,
}

#[derive(Clone, Copy, Debug)]
pub struct OptSpec {
    pub short: char,
    pub long: &'static str,
    pub has_arg: HasArg,
    pub multi: bool,
}

pub const SPECS: &[OptSpec] = &[
    OptSpec { short: 'd', long: "depth", has_arg: HasArg::Maybe, multi: false },
    OptSpec { short: 'a', long: "aggr", has_arg: HasArg::Maybe, multi: false },
    OptSpec { short: 's', long: "summary", has_arg: HasArg::No, multi: false },
    OptSpec { short: 'u', long: "usage", has_arg: HasArg::No, multi: false },
    OptSpec { short: 'b', long: "bytes", has_arg: HasArg::No, multi: false },
    OptSpec { short: 'f', long: "files-only", has_arg: HasArg::No, multi: false },
    OptSpec { short: 'x', long: "exclude", has_arg: HasArg::Yes, multi: true },
    OptSpec { short: 'H', long: "no-hidden", has_arg: HasArg::No, multi: false },
    OptSpec { short: 'A', long: "ascii", has_arg: HasArg::No, multi: false },
    OptSpec { short: 'h', long: "help", has_arg: HasArg::No, multi: false },
    OptSpec { short: 'v', long: "version", has_arg: HasArg::No, multi: false },
];

#[derive(Clone, Debug)]
pub struct Occurrence {
    pub spec_index: usize,
    pub value: Option<String>,
}

#[derive(Clone, Debug, Default)]
pub struct Matches {
    pub occurrences: Vec<Occurrence>,
    pub free: Vec<String>,
}

impl Matches {
    fn record(&mut self, spec_index: usize, value: Option<String>) {
        self.occurrences.push(Occurrence { spec_index, value });
    }

    pub fn present(&self, short: char) -> bool {
        self.occurrences.iter().any(|o| SPECS[o.spec_index].short == short)
    }

    pub fn count(&self, short: char) -> usize {
        self.occurrences.iter().filter(|o| SPECS[o.spec_index].short == short).count()
    }

    pub fn value(&self, short: char) -> Option<Option<&str>> {
        self.occurrences
            .iter()
            .find(|o| SPECS[o.spec_index].short == short)
            .map(|o| o.value.as_deref())
    }

    pub fn multi_values(&self, short: char) -> Vec<String> {
        self.occurrences
            .iter()
            .filter(|o| SPECS[o.spec_index].short == short)
            .filter_map(|o| o.value.clone())
            .collect()
    }
}

#[derive(Clone, Debug)]
pub enum Fail {
    UnrecognizedOption(String),
    OptionMissingArgument(String),
    UnexpectedArgument(String),
    OptionDuplicated(String),
}

impl std::fmt::Display for Fail {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        match self {
            Fail::UnrecognizedOption(s) => write!(f, "Unrecognized option: '{}'", s),
            Fail::OptionMissingArgument(s) => write!(f, "Argument to option '{}' missing", s),
            Fail::UnexpectedArgument(s) => write!(f, "Option '{}' does not take an argument", s),
            Fail::OptionDuplicated(s) => write!(f, "Option '{}' given more than once", s),
        }
    }
}

fn find_long(name: &str) -> Option<usize> {
    SPECS.iter().position(|s| s.long == name)
}

fn find_short(c: char) -> Option<usize> {
    SPECS.iter().position(|s| s.short == c)
}

/// Parse arguments after the program name. Free arguments may be intermixed
/// with options ("floating frees") until a literal `--` is seen.
pub fn parse(args: &[String]) -> Result<Matches, Fail> {
    let mut matches = Matches::default();
    let mut only_free = false;
    let mut i = 0usize;

    while i < args.len() {
        let arg = &args[i];
        if only_free {
            matches.free.push(arg.clone());
            i += 1;
            continue;
        }
        if arg == "--" {
            only_free = true;
            i += 1;
            continue;
        }
        if let Some(body) = arg.strip_prefix("--") {
            // Long option. Split on the first '='.
            let (name, inline_value) = match body.find('=') {
                Some(eq) => (&body[..eq], Some(body[eq + 1..].to_string())),
                None => (body, None),
            };
            let spec_index = match find_long(name) {
                Some(idx) => idx,
                None => return Err(Fail::UnrecognizedOption(name.to_string())),
            };
            let spec = &SPECS[spec_index];
            match spec.has_arg {
                HasArg::No => {
                    if inline_value.is_some() {
                        return Err(Fail::UnexpectedArgument(name.to_string()));
                    }
                    matches.record(spec_index, None);
                }
                HasArg::Maybe => {
                    // A separate following argument is never consumed
                    // for an optional-value long option.
                    matches.record(spec_index, inline_value);
                }
                HasArg::Yes => {
                    if let Some(v) = inline_value {
                        matches.record(spec_index, Some(v));
                    } else if i + 1 < args.len() {
                        i += 1;
                        matches.record(spec_index, Some(args[i].clone()));
                    } else {
                        return Err(Fail::OptionMissingArgument(name.to_string()));
                    }
                }
            }
            i += 1;
            continue;
        }
        if arg.starts_with('-') && arg.len() > 1 {
            // A group of short options, one Unicode scalar at a time.
            // Iterate over byte indices of the characters following '-'.
            let mut char_indices = arg.char_indices();
            let _ = char_indices.next(); // '-'
            let mut consumed_rest = false;
            for (byte_idx, c) in char_indices {
                let spec_index = match find_short(c) {
                    Some(idx) => idx,
                    None => return Err(Fail::UnrecognizedOption(c.to_string())),
                };
                let spec = &SPECS[spec_index];
                let rest_start = byte_idx + c.len_utf8();
                let rest = &arg[rest_start..];
                match spec.has_arg {
                    HasArg::No => {
                        matches.record(spec_index, None);
                    }
                    HasArg::Maybe => {
                        if !rest.is_empty() {
                            matches.record(spec_index, Some(rest.to_string()));
                        } else if i + 1 < args.len() {
                            let next = &args[i + 1];
                            // Consume the next argument as the value
                            // unless it looks like an option. A bare
                            // "-" is consumed; "--" is not.
                            let looks_like_option = next.starts_with('-') && next.chars().count() > 1;
                            if looks_like_option {
                                matches.record(spec_index, None);
                            } else {
                                i += 1;
                                matches.record(spec_index, Some(next.clone()));
                            }
                        } else {
                            matches.record(spec_index, None);
                        }
                        consumed_rest = true;
                        break;
                    }
                    HasArg::Yes => {
                        if !rest.is_empty() {
                            matches.record(spec_index, Some(rest.to_string()));
                        } else if i + 1 < args.len() {
                            i += 1;
                            matches.record(spec_index, Some(args[i].clone()));
                        } else {
                            return Err(Fail::OptionMissingArgument(c.to_string()));
                        }
                        consumed_rest = true;
                        break;
                    }
                }
            }
            let _ = consumed_rest;
            i += 1;
            continue;
        }
        // A bare "-" or any non-option is a free argument.
        matches.free.push(arg.clone());
        i += 1;
    }

    // Duplicate options are only reported after the whole command line
    // has been scanned without a more immediate error, and are reported
    // in the order the options were defined.
    for (idx, spec) in SPECS.iter().enumerate() {
        if !spec.multi {
            let n = matches.occurrences.iter().filter(|o| o.spec_index == idx).count();
            if n > 1 {
                return Err(Fail::OptionDuplicated(spec.long.to_string()));
            }
        }
    }

    Ok(matches)
}
