use std::collections::HashMap;
use std::env;
use std::fs;
use std::io::{self, IsTerminal};
use std::os::unix::ffi::OsStrExt;
use std::os::unix::fs::MetadataExt;
use std::path::{Path, PathBuf};

struct Cfg {
    depth: Option<u8>,
    aggr: Option<u64>,
    usage: bool,
    show_bytes: bool,
    files_only: bool,
    exclude: Vec<String>,
    no_hidden: bool,
    ascii: bool,
    colors: HashMap<String, String>,
}

struct Node {
    name: String,
    size: u64,
    children: Vec<Node>,
    color: Option<String>,
}

fn print_usage(program: &str) {
    println!(
        "Usage: {} [options] <path> [<path>..]\n\nOptions:\n    -d, --depth [DEPTH] show directories up to depth N (def 1)\n    -a, --aggr [N[KMG]] aggregate smaller than N B/KiB/MiB/GiB (def 1M)\n    -s, --summary       equivalent to -da, or -d1 -a1M\n    -u, --usage         report real disk usage instead of file size\n    -b, --bytes         print sizes in bytes\n    -f, --files-only    skip directories for a fast local overview\n    -x, --exclude NAME  exclude matching files or directories\n    -H, --no-hidden     exclude hidden files\n    -A, --ascii         ASCII characters only, no colors\n    -h, --help          show help\n    -v, --version       print version number",
        program
    );
}

fn parse_ls_colors() -> HashMap<String, String> {
    let mut map = HashMap::new();
    let text = env::var("LS_COLORS").unwrap_or_default();
    for entry in text.split(':') {
        if entry.is_empty() {
            break;
        }
        let mut parts = entry.split('=');
        let key = parts.next().unwrap().to_string();
        let value = parts.next().unwrap().to_string();
        map.insert(key, value);
    }
    map
}

fn parse_size(s: &str) -> Result<u64, ()> {
    let mut digits = String::new();
    let mut chars = s.chars().peekable();
    while chars.peek().map(|c| c.is_numeric()).unwrap_or(false) {
        digits.push(chars.next().unwrap());
    }
    if digits.is_empty() {
        return Err(());
    }
    let suffix = chars.next();
    if chars.next().is_some() {
        return Err(());
    }
    let n: u64 = digits.parse().unwrap();
    let mult: u64 = match suffix {
        Some('K') | Some('k') => 1024,
        Some('M') | Some('m') => 1024 * 1024,
        Some('G') | Some('g') => 1024 * 1024 * 1024,
        Some('T') | Some('t') => 1024 * 1024 * 1024 * 1024,
        _ => 1,
    };
    Ok(n.wrapping_mul(mult))
}

fn format_size(size: u64, in_bytes: bool) -> String {
    const KIB: u64 = 1024;
    const MIB: u64 = 1024 * 1024;
    const GIB: u64 = 1024 * 1024 * 1024;
    const TIB: u64 = 1024 * 1024 * 1024 * 1024;
    if in_bytes || size < KIB {
        format!("{} B", size)
    } else if size < MIB {
        format!("{:.2} KiB", size as f64 / KIB as f64)
    } else if size < GIB {
        format!("{:.2} MiB", size as f64 / MIB as f64)
    } else if size < TIB {
        format!("{:.2} GiB", size as f64 / GIB as f64)
    } else {
        format!("{:.2} TiB", size as f64 / TIB as f64)
    }
}

fn display_name(path: &Path) -> String {
    if let Some(name) = path.file_name() {
        return name.to_str().unwrap_or("[invalid name]").to_string();
    }
    let canon = path.canonicalize().unwrap();
    if let Some(name) = canon.file_name() {
        name.to_str().unwrap_or("[invalid name]").to_string()
    } else {
        canon.to_str().unwrap_or("[invalid name]").to_string()
    }
}

fn own_size(md: &fs::Metadata, usage: bool) -> u64 {
    if usage {
        md.blocks().wrapping_mul(512)
    } else {
        md.len()
    }
}

fn get_size(path: &Path, usage: bool) -> u64 {
    let md = match fs::symlink_metadata(path) {
        Ok(m) => m,
        Err(_) => return 0,
    };
    let own = own_size(&md, usage);
    if !md.is_dir() {
        return own;
    }
    match fs::read_dir(path) {
        Ok(entries) => {
            let mut total = own;
            for entry in entries.filter_map(|e| e.ok()) {
                total = total.wrapping_add(get_size(&entry.path(), usage));
            }
            total
        }
        Err(e) => {
            eprintln!("Couldn't read {} ({:?})", display_name(path), e.kind());
            own
        }
    }
}

fn color_for(path: &Path, md: &fs::Metadata, colors: &HashMap<String, String>) -> Option<String> {
    if colors.is_empty() {
        return None;
    }
    let mode = md.mode();
    if md.file_type().is_symlink() {
        let target_exists = path
            .read_link()
            .map(|target| target.exists())
            .unwrap_or(false);
        if target_exists {
            if let Some(c) = colors.get("ln") {
                return Some(c.clone());
            }
            if let Some(c) = colors.get("or") {
                return Some(c.clone());
            }
        } else if let Some(c) = colors.get("or") {
            return Some(c.clone());
        }
    }
    if path.is_dir() {
        if mode & 0o002 != 0 {
            if let Some(c) = colors.get("ow") {
                return Some(c.clone());
            }
        }
        if let Some(c) = colors.get("di") {
            return Some(c.clone());
        }
    }
    if mode & 0o111 != 0 {
        if let Some(c) = colors.get("ex") {
            return Some(c.clone());
        }
    }
    if let Some(ext) = path.extension().and_then(|v| v.to_str()) {
        if let Some(c) = colors.get(&format!("*.{}", ext)) {
            return Some(c.clone());
        }
    }
    if !path.is_file() {
        if let Some(c) = colors.get("bd") {
            return Some(c.clone());
        }
    } else if let Some(c) = colors.get("fi") {
        return Some(c.clone());
    }
    None
}

fn build_node(path: PathBuf, cfg: &Cfg, depth: Option<u8>) -> Node {
    let name = display_name(&path);
    let md = match fs::symlink_metadata(&path) {
        Ok(m) => m,
        Err(_) => {
            return Node {
                name,
                size: 0,
                children: Vec::new(),
                color: None,
            }
        }
    };
    let color = color_for(&path, &md, &cfg.colors);
    if !md.is_dir() {
        return Node {
            name,
            size: own_size(&md, cfg.usage),
            children: Vec::new(),
            color,
        };
    }
    if depth == Some(0) {
        return Node {
            name,
            size: get_size(&path, cfg.usage),
            children: Vec::new(),
            color,
        };
    }

    let mut size = own_size(&md, cfg.usage);
    let mut children: Vec<Node> = Vec::new();
    match fs::read_dir(&path) {
        Ok(entries) => {
            let child_depth = depth.map(|d| d - 1);
            for entry in entries.filter_map(|e| e.ok()) {
                let child_path = entry.path();
                let child_name = display_name(&child_path);
                if cfg.exclude.iter().any(|x| x == &child_name) {
                    continue;
                }
                if cfg.no_hidden && child_name.starts_with('.') {
                    continue;
                }
                if cfg.files_only && child_path.is_dir() {
                    continue;
                }
                let child = build_node(child_path, cfg, child_depth);
                size = size.wrapping_add(child.size);
                children.push(child);
            }
        }
        Err(e) => {
            eprintln!("Couldn't read {} ({:?})", name, e.kind());
            eprintln!("Couldn't read {} ({:?})", name, e.kind());
        }
    }

    children.sort_unstable_by(|a, b| b.size.cmp(&a.size));

    if let Some(limit) = cfg.aggr {
        let mut kept: Vec<Node> = Vec::new();
        let mut aggregated: u64 = 0;
        for child in children.into_iter() {
            if child.size < limit {
                aggregated = aggregated.wrapping_add(child.size);
            } else {
                kept.push(child);
            }
        }
        if aggregated > 0 {
            kept.push(Node {
                name: "<aggregated>".to_string(),
                size: aggregated,
                children: Vec::new(),
                color: None,
            });
        }
        children = kept;
    }

    Node {
        name,
        size,
        children,
        color,
    }
}

// ---- terminal handling ----

#[repr(C)]
struct Winsize {
    ws_row: u16,
    ws_col: u16,
    ws_xpixel: u16,
    ws_ypixel: u16,
}

extern "C" {
    fn ioctl(fd: i32, request: std::os::raw::c_ulong, ...) -> i32;
}

fn terminal_width() -> usize {
    if !io::stdout().is_terminal() {
        return 80;
    }
    let mut ws = Winsize {
        ws_row: 0,
        ws_col: 0,
        ws_xpixel: 0,
        ws_ypixel: 0,
    };
    let ret = unsafe { ioctl(1, 0x5413, &mut ws as *mut Winsize) };
    if ret == 0 && ws.ws_col > 0 {
        ws.ws_col as usize
    } else {
        80
    }
}

struct Printer {
    name_width: usize,
    graph_width: usize,
    show_bytes: bool,
    ascii: bool,
    use_colors: bool,
}

impl Printer {
    fn new(cfg: &Cfg) -> Self {
        let term_width = terminal_width();
        let name_width = ((term_width.wrapping_sub(15)) / 4).max(25);
        let graph_width = term_width
            .wrapping_sub(name_width)
            .wrapping_sub(22);
        Printer {
            name_width,
            graph_width,
            show_bytes: cfg.show_bytes,
            ascii: cfg.ascii,
            use_colors: !cfg.ascii && io::stdout().is_terminal(),
        }
    }

    fn top_graph(&self, size: u64, max: u64) -> Vec<char> {
        let count = (self.graph_width as f64 * size as f64 / max as f64 - 1.0) as usize;
        let spaces = self.graph_width.wrapping_sub(count);
        let mut text = String::new();
        text.push_str(&" ".repeat(spaces));
        text.push_str(&"\u{2588}".repeat(count));
        text.chars().collect()
    }

    fn child_graph(&self, parent: &[char], size: u64, parent_size: u64, generation: usize) -> Vec<char> {
        let mut graph: Vec<char> = parent.to_vec();
        let mut lp = 0usize;
        while lp < graph.len() && graph[graph.len() - 1 - lp] == '\u{2588}' {
            lp += 1;
        }
        if lp == 0 {
            return graph;
        }
        let raw = (lp as f64 + 1.0) * size as f64 / parent_size as f64 - 1.0;
        let mut lc = raw as usize;
        if lc >= lp {
            lc = lp - 1;
        }
        let new_len = lp - lc;
        let shade = ['\u{2591}', '\u{2592}', '\u{2593}', '\u{2588}'][generation.min(3)];
        let start = graph.len() - lp;
        for i in 0..new_len {
            graph[start + i] = shade;
        }
        graph
    }

    fn graph_string(&self, graph: &[char]) -> String {
        graph
            .iter()
            .map(|&c| {
                if self.ascii && c != ' ' {
                    '#'
                } else {
                    c
                }
            })
            .collect()
    }

    fn print_group(
        &self,
        nodes: &[Node],
        parent_size: u64,
        indent: &str,
        parent_graph: Option<&Vec<char>>,
        generation: usize,
    ) {
        let max_size = nodes.iter().map(|n| n.size).max().unwrap_or(0);
        for (idx, node) in nodes.iter().enumerate() {
            let is_last = idx + 1 == nodes.len();
            let branch = if is_last { "\u{2514}\u{2500} " } else { "\u{251c}\u{2500} " };
            let plain_prefix = format!("{}{}", indent, branch);
            let prefix_width = width::str_width(&plain_prefix);
            if prefix_width > self.name_width {
                continue;
            }
            print!("{}", plain_prefix);

            let graph = match parent_graph {
                None => self.top_graph(node.size, max_size),
                Some(pg) => self.child_graph(pg, node.size, parent_size, generation),
            };

            // Truncate or pad the (prefix + name) field to name_width
            // display columns. When truncating, a wide character that
            // does not fully fit is dropped and no compensating padding
            // is added (matching the observed one-column underfill).
            let name_w = width::str_width(&node.name);
            let (shown_name, pad_count) = if prefix_width + name_w > self.name_width {
                let available = self.name_width - prefix_width;
                (truncate_name(&node.name, available), 0usize)
            } else {
                (node.name.clone(), self.name_width - prefix_width - name_w)
            };
            let shown_name = if self.use_colors {
                match &node.color {
                    Some(code) => format!("\u{1b}[{}m{}\u{1b}[0m", code, shown_name),
                    None => shown_name,
                }
            } else {
                shown_name
            };
            let padding = " ".repeat(pad_count);
            let percent = (node.size as f64 * 100.0 / parent_size as f64) as u64;
            println!(
                "{}{} \u{2502}{}\u{2502}{:>4}% {:>13}",
                shown_name,
                padding,
                self.graph_string(&graph),
                percent,
                format_size(node.size, self.show_bytes)
            );

            let child_indent = format!("{}{}", indent, if is_last { "   " } else { "\u{2502}  " });
            let child_generation = if parent_graph.is_none() { 0 } else { generation + 1 };
            self.print_group(&node.children, node.size, &child_indent, Some(&graph), child_generation);
        }
    }

    fn print_roots(&self, roots: &[Node]) {
        if roots.len() == 1 {
            let root = &roots[0];
            println!("[ {} {} ]", root.name, format_size(root.size, self.show_bytes));
            self.print_group(&root.children, root.size, "", None, 0);
        } else {
            let total = roots.iter().fold(0u64, |acc, n| acc.wrapping_add(n.size));
            println!("[ <collection> {} ]", format_size(total, self.show_bytes));
            self.print_group(roots, total, "", None, 0);
        }
    }
}

fn truncate_name(name: &str, max_width: usize) -> String {
    let mut out = String::new();
    let mut w = 0usize;
    for c in name.chars() {
        let cw = width::char_width(c);
        if w + cw > max_width {
            break;
        }
        out.push(c);
        w += cw;
    }
    out
}

pub fn run() {
    let args: Vec<String> = env::args().collect();
    let program: &str = args.get(0).map(|s| s.as_str()).unwrap_or("dutree");
    let rest: &[String] = if args.len() > 1 { &args[1..] } else { &[] };
    let matches = match opts::parse(rest) {
        Ok(m) => m,
        Err(e) => {
            print_usage(program);
            eprintln!("{}", e);
            std::process::exit(1);
        }
    };
    if matches.present('h') {
        print_usage(program);
        return;
    }
    if matches.present('v') {
        println!("dutree version 0.2.18");
        return;
    }

    let colors = parse_ls_colors();

    let mut path_strs = matches.free.clone();
    if path_strs.is_empty() {
        path_strs.push(".".to_string());
    }
    for p in &path_strs {
        if !Path::new(p).exists() {
            eprintln!("path {} doesn't exist", p);
            std::process::exit(1);
        }
    }

    let mut depth: Option<u8> = None;
    if matches.present('d') {
        depth = Some(match matches.value('d') {
            Some(Some(s)) => s.parse::<u8>().unwrap_or(1),
            _ => 1,
        });
    }

    let mut aggr: Option<u64> = None;
    if matches.present('a') {
        let arg_string: &str = match matches.value('a') {
            Some(Some(s)) => s,
            _ => "1M",
        };
        match parse_size(arg_string) {
            Ok(v) => aggr = Some(v),
            Err(()) => {
                eprintln!("invalid argument '{}'", arg_string);
                std::process::exit(1);
            }
        }
    }

    if matches.present('s') {
        depth = Some(1);
        aggr = Some(1024 * 1024);
    }

    let cfg = Cfg {
        depth,
        aggr,
        usage: matches.present('u'),
        show_bytes: matches.present('b'),
        files_only: matches.present('f'),
        exclude: matches.multi_values('x'),
        no_hidden: matches.present('H'),
        ascii: matches.present('A'),
        colors,
    };

    let _current_dir = env::current_dir().unwrap();

    let mut roots: Vec<Node> = path_strs
        .iter()
        .map(|p| build_node(PathBuf::from(p), &cfg, cfg.depth))
        .collect();
    roots.sort_unstable_by(|a, b| b.size.cmp(&a.size));

    let printer = Printer::new(&cfg);
    printer.print_roots(&roots);

    // Keep the current-dir handle alive until the tree has been built;
    // obtaining it above also mirrors the original's behaviour of
    // failing early when the working directory no longer exists.
    drop(_current_dir);
    // The OsStrExt import is retained for platforms where MetadataExt
    // methods are provided through it in older toolchains.
    let _ = std::ffi::OsStr::new("x").as_bytes();
}
