#[repr(C)]
struct Winsize {
    ws_row: u16,
    ws_col: u16,
    ws_xpixel: u16,
    ws_ypixel: u16,
}

extern "C" {
    fn ioctl(fd: i32, request: std::os::raw::c_ulong, ...) -> i32;
}

fn terminal_width() -> usize {
    if !io::stdout().is_terminal() {
        return 80;
    }
    let mut ws = Winsize {
        ws_row: 0,
        ws_col: 0,
        ws_xpixel: 0,
        ws_ypixel: 0,
    };
    let ret = unsafe { ioctl(1, 0x5413, &mut ws as *mut Winsize) };
    if ret == 0 && ws.ws_col > 0 {
        ws.ws_col as usize
    } else {
        80
    }
}

struct Printer {
    name_width: usize,
    graph_width: usize,
    show_bytes: bool,
    ascii: bool,
    use_colors: bool,
}

impl Printer {
    fn new(cfg: &Cfg) -> Self {
        let term_width = terminal_width();
        let name_width = ((term_width.wrapping_sub(15)) / 4).max(25);
        let graph_width = term_width
            .wrapping_sub(name_width)
            .wrapping_sub(22);
        Printer {
            name_width,
            graph_width,
            show_bytes: cfg.show_bytes,
            ascii: cfg.ascii,
            use_colors: !cfg.ascii && io::stdout().is_terminal(),
        }
    }

    fn top_graph(&self, size: u64, max: u64) -> Vec<char> {
        let count = (self.graph_width as f64 * size as f64 / max as f64 - 1.0) as usize;
        let spaces = self.graph_width.wrapping_sub(count);
        let mut text = String::new();
        text.push_str(&" ".repeat(spaces));
        text.push_str(&"\u{2588}".repeat(count));
        text.chars().collect()
    }

    fn child_graph(&self, parent: &[char], size: u64, parent_size: u64, generation: usize) -> Vec<char> {
        let mut graph: Vec<char> = parent.to_vec();
        let mut lp = 0usize;
        while lp < graph.len() && graph[graph.len() - 1 - lp] == '\u{2588}' {
            lp += 1;
        }
        if lp == 0 {
            return graph;
        }
        let raw = (lp as f64 + 1.0) * size as f64 / parent_size as f64 - 1.0;
        let mut lc = raw as usize;
        if lc >= lp {
            lc = lp - 1;
        }
        let new_len = lp - lc;
        let shade = ['\u{2591}', '\u{2592}', '\u{2593}', '\u{2588}'][generation.min(3)];
        let start = graph.len() - lp;
        for i in 0..new_len {
            graph[start + i] = shade;
        }
        graph
    }

    fn graph_string(&self, graph: &[char]) -> String {
        graph
            .iter()
            .map(|&c| {
                if self.ascii && c != ' ' {
                    '#'
                } else {
                    c
                }
            })
            .collect()
    }

    fn print_group(
        &self,
        nodes: &[Node],
        parent_size: u64,
        indent: &str,
        parent_graph: Option<&Vec<char>>,
        generation: usize,
    ) {
        let max_size = nodes.iter().map(|n| n.size).max().unwrap_or(0);
        for (idx, node) in nodes.iter().enumerate() {
            let is_last = idx + 1 == nodes.len();
            let branch = if is_last { "\u{2514}\u{2500} " } else { "\u{251c}\u{2500} " };
            let plain_prefix = format!("{}{}", indent, branch);
            let prefix_width = width::str_width(&plain_prefix);
            if prefix_width > self.name_width {
                continue;
            }
            print!("{}", plain_prefix);

            let graph = match parent_graph {
                None => self.top_graph(node.size, max_size),
                Some(pg) => self.child_graph(pg, node.size, parent_size, generation),
            };

            // Truncate or pad the (prefix + name) field to name_width
            // display columns. When truncating, a wide character that
            // does not fully fit is dropped and no compensating padding
            // is added (matching the observed one-column underfill).
            let name_w = width::str_width(&node.name);
            let (shown_name, pad_count) = if prefix_width + name_w > self.name_width {
                let available = self.name_width - prefix_width;
                (truncate_name(&node.name, available), 0usize)
            } else {
                (node.name.clone(), self.name_width - prefix_width - name_w)
            };
            let shown_name = if self.use_colors {
                match &node.color {
                    Some(code) => format!("\u{1b}[{}m{}\u{1b}[0m", code, shown_name),
                    None => shown_name,
                }
            } else {
                shown_name
            };
            let padding = " ".repeat(pad_count);
            let percent = (node.size as f64 * 100.0 / parent_size as f64) as u64;
            println!(
                "{}{} \u{2502}{}\u{2502}{:>4}% {:>13}",
                shown_name,
                padding,
                self.graph_string(&graph),
                percent,
                format_size(node.size, self.show_bytes)
            );

            let child_indent = format!("{}{}", indent, if is_last { "   " } else { "\u{2502}  " });
            let child_generation = if parent_graph.is_none() { 0 } else { generation + 1 };
            self.print_group(&node.children, node.size, &child_indent, Some(&graph), child_generation);
        }
    }

    fn print_roots(&self, roots: &[Node]) {
        if roots.len() == 1 {
            let root = &roots[0];
            println!("[ {} {} ]", root.name, format_size(root.size, self.show_bytes));
            self.print_group(&root.children, root.size, "", None, 0);
        } else {
            let total = roots.iter().fold(0u64, |acc, n| acc.wrapping_add(n.size));
            println!("[ <collection> {} ]", format_size(total, self.show_bytes));
            self.print_group(roots, total, "", None, 0);
        }
    }
}

fn truncate_name(name: &str, max_width: usize) -> String {
    let mut out = String::new();
    let mut w = 0usize;
    for c in name.chars() {
        let cw = width::char_width(c);
        if w + cw > max_width {
            break;
        }
        out.push(c);
        w += cw;
    }
    out
}

pub fn run() {
    let args: Vec<String> = env::args().collect();
    let program: &str = args.get(0).map(|s| s.as_str()).unwrap_or("dutree");
    let rest: &[String] = if args.len() > 1 { &args[1..] } else { &[] };
    let matches = match opts::parse(rest) {
        Ok(m) => m,
        Err(e) => {
            print_usage(program);
            eprintln!("{}", e);
            std::process::exit(1);
        }
    };
    if matches.present('h') {
        print_usage(program);
        return;
    }
    if matches.present('v') {
        println!("dutree version 0.2.18");
        return;
    }

    let colors = parse_ls_colors();

    let mut path_strs = matches.free.clone();
    if path_strs.is_empty() {
        path_strs.push(".".to_string());
    }
    for p in &path_strs {
        if !Path::new(p).exists() {
            eprintln!("path {} doesn't exist", p);
            std::process::exit(1);
        }
    }

    let mut depth: Option<u8> = None;
    if matches.present('d') {
        depth = Some(match matches.value('d') {
            Some(Some(s)) => s.parse::<u8>().unwrap_or(1),
            _ => 1,
        });
    }

    let mut aggr: Option<u64> = None;
    if matches.present('a') {
        let arg_string: &str = match matches.value('a') {
            Some(Some(s)) => s,
            _ => "1M",
        };
        match parse_size(arg_string) {
            Ok(v) => aggr = Some(v),
            Err(()) => {
                eprintln!("invalid argument '{}'", arg_string);
                std::process::exit(1);
            }
        }
    }

    if matches.present('s') {
        depth = Some(1);
        aggr = Some(1024 * 1024);
    }

    let cfg = Cfg {
        depth,
        aggr,
        usage: matches.present('u'),
        show_bytes: matches.present('b'),
        files_only: matches.present('f'),
        exclude: matches.multi_values('x'),
        no_hidden: matches.present('H'),
        ascii: matches.present('A'),
        colors,
    };

    let _current_dir = env::current_dir().unwrap();

    let mut roots: Vec<Node> = path_strs
        .iter()
        .map(|p| build_node(PathBuf::from(p), &cfg, cfg.depth))
        .collect();
    roots.sort_unstable_by(|a, b| b.size.cmp(&a.size));

    let printer = Printer::new(&cfg);
    printer.print_roots(&roots);

    // Keep the current-dir handle alive until the tree has been built;
    // obtaining it above also mirrors the original's behaviour of
    // failing early when the working directory no longer exists.
    drop(_current_dir);
    // The OsStrExt import is retained for platforms where MetadataExt
    // methods are provided through it in older toolchains.
    let _ = std::ffi::OsStr::new("x").as_bytes();
}
