fn class(c: char) -> Class {
    let cp = c as u32;
    match cp {
        0x000d => Class::Cr,
        0x000a => Class::Lf,
        0x200d => Class::Zwj,
        0x1f1e6..=0x1f1ff => Class::RegionalIndicator,
        0x1100..=0x115f | 0xa960..=0xa97c => Class::L,
        0x1160..=0x11a7 | 0xd7b0..=0xd7c6 => Class::V,
        0x11a8..=0x11ff | 0xd7fb..=0xd7ff => Class::T,
        0xac00..=0xd7a3 => {
            if (cp - 0xac00) % 28 == 0 {
                Class::Lv
            } else {
                Class::Lvt
            }
        }
        _ if is_prepend(cp) => Class::Prepend,
        _ if in_ranges(EXTEND, cp) => Class::Extend,
        _ if in_ranges(SPACING_MARK, cp) => Class::SpacingMark,
        _ if c.is_control() || cp == 0x2028 || cp == 0x2029 || in_ranges(FORMAT, cp) => {
            Class::Control
        }
        _ if is_extended_pictographic(cp) => Class::ExtendedPictographic,
        _ => Class::Other,
    }
}

fn is_break(
    prev: Class,
    curr: Class,
    ri_count: usize,
    extended_pictographic_before_zwj: bool,
) -> bool {
    if prev == Class::Cr && curr == Class::Lf {
        return false;
    }
    if matches!(prev, Class::Control | Class::Cr | Class::Lf) {
        return true;
    }
    if matches!(curr, Class::Control | Class::Cr | Class::Lf) {
        return true;
    }
    if prev == Class::L && matches!(curr, Class::L | Class::V | Class::Lv | Class::Lvt) {
        return false;
    }
    if matches!(prev, Class::Lv | Class::V) && matches!(curr, Class::V | Class::T) {
        return false;
    }
    if matches!(prev, Class::Lvt | Class::T) && curr == Class::T {
        return false;
    }
    if curr == Class::Extend || curr == Class::Zwj {
        return false;
    }
    if curr == Class::SpacingMark {
        return false;
    }
    if prev == Class::Prepend {
        return false;
    }
    if prev == Class::Zwj
        && curr == Class::ExtendedPictographic
        && extended_pictographic_before_zwj
    {
        return false;
    }
    if prev == Class::RegionalIndicator
        && curr == Class::RegionalIndicator
        && ri_count % 2 == 1
    {
        return false;
    }
    true
}

/// Split a string into extended grapheme clusters.
pub fn graphemes(s: &str) -> Vec<&str> {
    let mut result = Vec::new();
    let mut start = 0usize;
    let mut prev_class: Option<Class> = None;
    let mut ri_count = 0usize;
    let mut pictographic_before_zwj = false;

    for (idx, ch) in s.char_indices() {
        let cls = class(ch);
        if let Some(prev) = prev_class {
            if is_break(prev, cls, ri_count, pictographic_before_zwj) {
                result.push(&s[start..idx]);
                start = idx;
                ri_count = 0;
                pictographic_before_zwj = false;
            }
        }
        if cls == Class::RegionalIndicator {
            ri_count += 1;
        }
        if is_extended_pictographic(ch as u32) {
            pictographic_before_zwj = true;
        } else if cls != Class::Extend && cls != Class::Zwj {
            pictographic_before_zwj = false;
        }
        prev_class = Some(cls);
    }
    if start < s.len() {
        result.push(&s[start..]);
    }
    result
}
